# ---------- split / lsplit ----------

def test_split():
    yes, no = split(lambda x: x > 2, [1, 2, 3, 4])
    assert list(yes) == [3, 4]
    assert list(no) == [1, 2]


def test_split_interleaved():
    yes, no = split(lambda x: x % 2 == 0, [1, 2, 3, 4])
    assert list(no) == [1, 3]
    assert list(yes) == [2, 4]


def test_lsplit():
    yes, no = lsplit(lambda x: x > 2, [1, 2, 3, 4])
    assert yes == [3, 4]
    assert no == [1, 2]


def test_lsplit_pred_int():
    yes, no = lsplit(1, [(0, 'a'), (1, 'b'), (1, 'c')])
    assert yes == [(1, 'b'), (1, 'c')]
    assert no == [(0, 'a')]


